function spawnHazard() {
  // spawn at random edge, avoid player area
  const side = Math.random() < 0.5 ? 'top' : 'bottom';
  const x = Math.random() * canvas.width;
  const y = side === 'top' ? -20 : canvas.height + 20;
  const vy = side === 'top' ? HAZARD_SPEED : -HAZARD_SPEED;
  hazards.push({ x, y, vx: 0, vy });
}

